import math

def test_known_values():
    assert abs(solution.standard_error([2, 4, 6, 8, 10]) - 1.41421356) < 1e-6

def test_matches_formula():
    values = [1.0, 2.0, 3.0, 4.0, 10.0]
    want = solution.sample_sd(values) / math.sqrt(len(values))
    assert abs(solution.standard_error(values) - want) < 1e-12

def test_single_value_raises():
    try:
        solution.standard_error([5.0])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_returns_float():
    assert isinstance(solution.standard_error([1, 2, 3]), float)

def test_no_mutation():
    values = [1.0, 2.0, 3.0]
    solution.standard_error(values)
    assert values == [1.0, 2.0, 3.0]

def test_more_data_is_tighter():
    values = [1.0, 2.0, 3.0, 4.0]
    assert solution.standard_error(values * 4) < solution.standard_error(values)
